CREATE TABLE users (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE COLLATE NOCASE, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('reporter','producer','editor','chief','media','social','legal','freelancer','admin','executive')), desk TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)), created_at TEXT NOT NULL);
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires_at INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX sessions_user ON sessions(user_id);
CREATE TABLE login_attempts (key TEXT PRIMARY KEY, attempts INTEGER NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE assignments (id TEXT PRIMARY KEY, title TEXT NOT NULL, briefing TEXT NOT NULL, desk TEXT NOT NULL, priority TEXT NOT NULL CHECK(priority IN ('low','normal','high','urgent')), assignee_id TEXT NOT NULL REFERENCES users(id), editor_id TEXT NOT NULL REFERENCES users(id), deadline TEXT NOT NULL, location TEXT NOT NULL DEFAULT '', tags TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'draft', version INTEGER NOT NULL DEFAULT 1, created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX assignments_assignee_deadline ON assignments(assignee_id,deadline);
CREATE INDEX assignments_desk_status ON assignments(desk,status);
CREATE TABLE stories (id TEXT PRIMARY KEY, assignment_id TEXT REFERENCES assignments(id), title TEXT NOT NULL, subtitle TEXT NOT NULL DEFAULT '', body TEXT NOT NULL DEFAULT '', slug TEXT NOT NULL UNIQUE, desk TEXT NOT NULL, tags TEXT NOT NULL DEFAULT '', seo_description TEXT NOT NULL DEFAULT '', author_id TEXT NOT NULL REFERENCES users(id), status TEXT NOT NULL DEFAULT 'draft', version INTEGER NOT NULL DEFAULT 1, approved_version INTEGER, scheduled_at TEXT, published_at TEXT, embargo TEXT, sensitive INTEGER NOT NULL DEFAULT 0 CHECK(sensitive IN (0,1)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX stories_desk_status ON stories(desk,status);
CREATE INDEX stories_schedule ON stories(status,scheduled_at);
CREATE TABLE story_versions (id TEXT PRIMARY KEY, story_id TEXT NOT NULL REFERENCES stories(id), version INTEGER NOT NULL, snapshot TEXT NOT NULL, actor_id TEXT NOT NULL REFERENCES users(id), reason TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(story_id,version));
CREATE TABLE publications (id TEXT PRIMARY KEY, story_id TEXT NOT NULL REFERENCES stories(id), version INTEGER NOT NULL, snapshot TEXT NOT NULL, actor_id TEXT NOT NULL REFERENCES users(id), active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, UNIQUE(story_id,version));
CREATE TABLE sources (id TEXT PRIMARY KEY, encrypted_data TEXT NOT NULL, owner_id TEXT NOT NULL REFERENCES users(id), confidentiality TEXT NOT NULL CHECK(confidentiality IN ('internal','confidential')), created_at TEXT NOT NULL);
CREATE TABLE assignment_notes (id TEXT PRIMARY KEY, assignment_id TEXT NOT NULL REFERENCES assignments(id), body TEXT NOT NULL, actor_id TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL);
CREATE TABLE assignment_sources (assignment_id TEXT NOT NULL REFERENCES assignments(id), source_id TEXT NOT NULL REFERENCES sources(id), PRIMARY KEY(assignment_id,source_id));
CREATE TABLE tasks (id TEXT PRIMARY KEY, title TEXT NOT NULL, assignee_id TEXT NOT NULL REFERENCES users(id), assignment_id TEXT REFERENCES assignments(id), deadline TEXT NOT NULL, priority TEXT NOT NULL, completed INTEGER NOT NULL DEFAULT 0 CHECK(completed IN (0,1)), created_by TEXT NOT NULL REFERENCES users(id));
CREATE INDEX tasks_assignee ON tasks(assignee_id,completed);
CREATE TABLE notifications (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), title TEXT NOT NULL, href TEXT NOT NULL, read_at TEXT, created_at TEXT NOT NULL);
CREATE INDEX notifications_user ON notifications(user_id,created_at);
CREATE TABLE audit_events (id TEXT PRIMARY KEY, actor_id TEXT NOT NULL REFERENCES users(id), entity_id TEXT NOT NULL, action TEXT NOT NULL, reason TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL);
CREATE INDEX audit_entity ON audit_events(entity_id,created_at);
CREATE TRIGGER audit_no_update BEFORE UPDATE ON audit_events BEGIN SELECT RAISE(ABORT,'Audit events are immutable'); END;
CREATE TRIGGER audit_no_delete BEFORE DELETE ON audit_events BEGIN SELECT RAISE(ABORT,'Audit events are immutable'); END;
CREATE TABLE idempotency (key TEXT NOT NULL, actor_id TEXT NOT NULL REFERENCES users(id), fingerprint TEXT NOT NULL, response TEXT NOT NULL, created_at INTEGER NOT NULL, PRIMARY KEY(key,actor_id));
